type UpdateFileLocationParams struct {
	Name     string `json:"name"`
	FolderID int64  `json:"folder_id"`
	ID       int64  `json:"id"`
}

func (q *Queries) UpdateFileLocation(ctx context.Context, arg UpdateFileLocationParams) (File, error) {
	row := q.db.QueryRowContext(ctx, updateFileLocation, arg.Name, arg.FolderID, arg.ID)
	var i File
	err := row.Scan(
		&i.ID,
		&i.FolderID,
		&i.Name,
		&i.Size,
		&i.Mime,
		&i.Mtime,
		&i.Layout,
		&i.DataShards,
		&i.ParityShards,
		&i.ChunkSize,
		&i.Sha256,
		&i.Status,
		&i.CreatedAt,
		&i.DeletedAt,
		&i.Etag,
		&i.Internal,
		&i.Meta,
		&i.OwnerID,
		&i.EncKey,
	)
	return i, err
}

const updateFileRemote = `-- name: UpdateFileRemote :exec
UPDATE files SET name = ?, size = ?, mime = ?, mtime = ? WHERE id = ?
`

type UpdateFileRemoteParams struct {
	Name  string `json:"name"`
	Size  int64  `json:"size"`
	Mime  string `json:"mime"`
	Mtime int64  `json:"mtime"`
	ID    int64  `json:"id"`
}

func (q *Queries) UpdateFileRemote(ctx context.Context, arg UpdateFileRemoteParams) error {
	_, err := q.db.ExecContext(ctx, updateFileRemote,
		arg.Name,
		arg.Size,
		arg.Mime,
		arg.Mtime,
		arg.ID,
	)
	return err
}
